// Sets traceId + userId in MDC for EVERY request — appears in every log line
package com.bank.audit.filter;

import jakarta.servlet.*;
import jakarta.servlet.http.*;
import lombok.extern.slf4j.Slf4j;
import org.slf4j.MDC;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import java.io.IOException;
import java.util.UUID;

@Component
@Order(1)  // run before other filters
@Slf4j
public class CorrelationIdFilter extends OncePerRequestFilter {

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                     FilterChain chain) throws ServletException, IOException {
        // Read trace ID from header (set by API gateway) or generate new one
        String traceId = request.getHeader("X-Request-ID");
        if (traceId == null || traceId.isBlank()) {
            traceId = UUID.randomUUID().toString().substring(0, 8);
        }

        // Extract userId from JWT token (simplified)
        String userId = request.getHeader("X-User-ID");

        // Set in MDC — ThreadLocal, appears in log pattern as %X{traceId}
        MDC.put("traceId", traceId);
        if (userId != null) MDC.put("userId", userId);

        // Echo trace ID back in response header
        response.setHeader("X-Request-ID", traceId);

        try {
            log.debug("Request: {} {} (traceId={})", request.getMethod(), request.getRequestURI(), traceId);
            chain.doFilter(request, response);
        } finally {
            // CRITICAL: clear MDC — thread returns to pool, next request would inherit stale values
            MDC.clear();
        }
    }
}
