// Mask sensitive data BEFORE logging — never log raw PII
package com.bank.audit.util;

public final class PiiMasker {

    private PiiMasker() {}

    public static String maskAccountId(String accountId) {
        if (accountId == null || accountId.length() < 4) return "****";
        return "****" + accountId.substring(accountId.length() - 4);
    }

    public static String maskEmail(String email) {
        if (email == null || !email.contains("@")) return "****";
        int atIndex = email.indexOf("@");
        return email.substring(0, Math.min(2, atIndex)) + "****" + email.substring(atIndex);
    }

    public static String maskPhone(String phone) {
        if (phone == null || phone.length() < 4) return "****";
        return "****" + phone.substring(phone.length() - 4);
    }
}
