package com.bank.audit.controller;

import com.bank.audit.dto.AuditEvent;
import com.bank.audit.model.AuditLog;
import com.bank.audit.repository.AuditLogRepository;
import com.bank.audit.service.AuditService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/audit")
@RequiredArgsConstructor
public class AuditController {

    private final AuditService auditService;
    private final AuditLogRepository auditRepo;

    @PostMapping("/events")
    @ResponseStatus(HttpStatus.CREATED)
    public void recordEvent(@RequestBody @Valid AuditEvent event) {
        auditService.recordEvent(event);
    }

    @GetMapping("/trace/{traceId}")
    public List<AuditLog> getByTrace(@PathVariable String traceId) {
        return auditRepo.findByTraceId(traceId);
    }
}
