import org.mockito.junit.jupiter.MockitoExtension;
import org.slf4j.MDC;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class AuditServiceTest {

    @Mock AuditLogRepository auditRepo;
    @InjectMocks AuditService auditService;

    @BeforeEach
    void setUp() {
        MDC.put("traceId", "test-trace-001");
        MDC.put("userId", "test-user");
    }

    @Test
    void shouldRecordAuditEventWithTraceId() {
        when(auditRepo.save(any(AuditLog.class))).thenAnswer(i -> i.getArgument(0));

        auditService.recordEvent(new AuditEvent(
            "TRANSFER", "Account", "SAV2001", "SAV2001", "Transfer Rs.50000"));

        ArgumentCaptor<AuditLog> captor = ArgumentCaptor.forClass(AuditLog.class);
        verify(auditRepo).save(captor.capture());
        assertThat(captor.getValue().getTraceId()).isEqualTo("test-trace-001");
        assertThat(captor.getValue().getAction()).isEqualTo("TRANSFER");
    }
}
